        tex = r"\sum_{%s=%s}^{%s} " % \
            tuple([ self._print(i) for i in expr.limits[0] ])
    else:
        def _format_ineq(l):
            return r"%s \leq %s \leq %s" % \
                tuple([self._print(s) for s in (l[1], l[0], l[2])])

        tex = r"\sum_{\substack{%s}} " % \
